# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# All generated local configuration is ignored; secrets live outside the repo.
VITA_REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
cd "$VITA_REPO"
VITA_LOCAL="$VITA_REPO/.scratch/independent-web-v1/local"
umask 077
mkdir -p "$VITA_LOCAL"
ENV_FILE="$VITA_LOCAL/cutover.env"
if [[ -L "$VITA_LOCAL" || -L "$ENV_FILE" || ( -e "$ENV_FILE" && ! -f "$ENV_FILE" ) ]]; then
  printf '拒绝通过链接或非普通文件保存部署配置。\n' >&2; exit 1
fi
chmod 700 "$VITA_LOCAL"
[[ ! -e "$ENV_FILE" ]] || chmod 600 "$ENV_FILE"

record() {
  local record_key="$1" record_prompt="$2" record_pattern="${3:-.+}"
  ask "$record_key" "$record_prompt"
  if [[ ! "${!record_key}" =~ $record_pattern ]]; then warn "输入无效；已停止，请核对后重跑。"; exit 1; fi
  write_env "$record_key" "${!record_key}"
}
gate() { confirm "$1" || { warn '未确认；停止在当前步骤，未记录验收通过。'; exit 1; }; }
show_cmd() { printf '  '; printf '%q ' "$@"; printf '\n'; }
origin() {
  record "$1" "$2"
  node --input-type=module - "${!1}" <<'JS'
const url = new URL(process.argv[2]);
if (url.protocol !== 'https:' || url.username || url.password || url.pathname !== '/' || url.search || url.hash) throw new Error('必须是没有路径或凭据的 HTTPS origin');
JS
}

