record CF_LOGIN_CPU_MS '目标平台观测的登录 CPU（毫秒）：' '^[0-9]+([.][0-9]+)?$'
export CF_LOGIN_CPU_MS CF_CPU_BUDGET_MS
node --input-type=module -e 'const budget=Number(process.env.CF_CPU_BUDGET_MS), used=Number(process.env.CF_LOGIN_CPU_MS); if(!(budget>0 && used>=0 && used<budget)) throw new Error("CPU 余量不足，停止；升级套餐或变更迭代数须另行记录决定")'
gate '已确认 100000 次 PBKDF2 在当前套餐成功，CPU 证据是目标平台观测，未静默下调迭代数'

stage '预览安全、审计、平台限流与恢复演练'
open_url 'https://developers.cloudflare.com/waf/rate-limiting-rules/create-zone-dashboard/'
step '按 runbook 验收矩阵配置并验证平台规则，覆盖 login、写入、备份/导出；封闭 pages.dev 绕过路径。套餐不支持完整规则时停止，不以 isolate 内计数代替。'
step '合成数据验证会话到期/注销、CSRF、匿名写入、备份泄露、冲突、故障、审计事务/分页/保留及 schema 旧行保留。'
step '按 d1-backup-recovery.md 在预览 D1 做 JSON 恢复与 Time Travel，恢复后撤销旧会话。unknown 元数据缺失属于契约故障注入；无法在原生 D1 注入时保持未验证。'
step '在 .scratch/independent-web-v1/evidence/06.1-06-cloudflare.md 逐项记录脱敏结果，pending 不能当 pass。'
gate '预览验收矩阵全部有目标环境证据；未出现阻断项，回滚和 D1 绑定均已核对'

stage '隔离状态下的生产发布、冻结来源与首次迁移'
origin CF_PRODUCTION_ORIGIN '实际生产 HTTPS origin（仍限制本人访问）：'
record CF_SOURCE_SQLITE '本机真实 SQLite 来源（绝对路径）：' '^/'
step '停止本机健康数据写入，保留原 SQLite 和现有备份；之后在线 D1 是唯一事实来源。'
show_cmd wrangler pages deploy dist --config "$CF_CONFIG_PATH" --project-name "$CF_PAGES_PROJECT" --branch "$CF_PRODUCTION_BRANCH"
gate '已核对生产数据库为空、Secret/迁移/产物一致，并手动发布；所有入口仍隔离'
show_cmd npm run d1:cutover -- --origin "$CF_PRODUCTION_ORIGIN" --credentials "$CF_PRODUCTION_CREDENTIALS" --sqlite "$CF_SOURCE_SQLITE" --directory "$CF_BACKUP_DIRECTORY"
say '核对类型数量、日期、营养和设置后，追加 --confirm --source-sha256 <生产预览摘要> 执行一次。'
say '只有 reconciled=true 且迁移前后 JSON/SQLite 均落盘才继续。中断时先检查在线版本，绝不清库重试。'
gate '本人已确认真实来源并执行首次迁移，对账通过且完整备份落盘；原 SQLite 保留'

stage '生产备份、定时任务、恢复与会话撤销'
show_cmd npm run d1:backup -- backup --origin "$CF_PRODUCTION_ORIGIN" --credentials "$CF_PRODUCTION_CREDENTIALS" --directory "$CF_BACKUP_DIRECTORY"
open_url 'https://developers.cloudflare.com/d1/reference/time-travel/'
step '按备份指南，在维护窗口确认真实 D1 与 bookmark 后演练平台恢复；先保留安全副本，随后清除 owner_session、核对 schema/完整数据。由本人确认覆盖。'
step '使用 ops/d1-backup.launchd.plist.example，替换全部真实路径/origin；权限 0600 日志置于 0700 目录。先运行成功，再由本人安装到 LaunchAgents。'
step '实际触发任务并核对退出码、新备份文件、权限及导出时间；仅 plist 语法通过不能验收定时备份。'
gate '生产恢复、历史会话撤销、备份失败停止恢复、版本冲突和定时任务实际运行均已有证据'

stage '自定义域名公网切换与生产验收'
open_url 'https://developers.cloudflare.com/pages/configuration/custom-domains/'
step '最后核对证据矩阵：CPU、访问隔离、迁移/备份、平台限流、Time Travel、schema、回滚均已通过。'
gate '确认允许真实生产健康看板公开，且已经准备立即重新封闭访问的回滚路径'
step '由本人解除生产自定义域名的访问隔离；预览与 pages.dev 历史入口继续受保护。逐个检查没有通过别名绕过平台限流。'
step '无痕访客读取；本人保存后访客刷新见新数据；本人注销后编辑失败。真实桌面与移动浏览器按矩阵复验。'
step '出现故障立即重新封闭访问。回滚旧 Pages 部署不回滚 D1；数据回滚先备份并由本人确认。'
gate '生产验收已取证且没有 pending/blocker，旧入口状态与回滚路径已记录'
finish
say '以上是本人执行记录；agent 尚未独立验收。核对证据后再关闭 #06.1-06 与 #06.1-05，不能只凭向导运行结束关票。'
